const _CW_CHAIN_IMG = 'data:image/png;base64,';

// ── Web Audio snap / reverb ───────────────────────────────────────────────────
let _cwAudioCtx = null;
function _cwAudio() {
    if (!_cwAudioCtx) {
        try { _cwAudioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){}
    }
    return _cwAudioCtx;
}

function playSnapLock() {
    const ctx = _cwAudio();
    if (!ctx) return;
    try {
        const sr      = ctx.sampleRate;
        const snapLen = Math.floor(sr * 0.28);
        const snapBuf = ctx.createBuffer(1, snapLen, sr);
        const d       = snapBuf.getChannelData(0);
        for (let i = 0; i < snapLen; i++) {
            const t   = i / sr;
            const env = Math.exp(-t * 60) * 0.95 + Math.exp(-t * 16) * 0.45;
            const click  = Math.sin(2 * Math.PI * 190 * t) * Math.exp(-t * 65);
            const thud   = Math.sin(2 * Math.PI * 52  * t) * Math.exp(-t * 18) * 1.2;
            const ring   = Math.sin(2 * Math.PI * 880 * t) * Math.exp(-t * 90) * 0.3;
            const ring2  = Math.sin(2 * Math.PI * 1320* t) * Math.exp(-t * 120)* 0.15;
            const noise  = (Math.random() * 2 - 1) * Math.exp(-t * 55) * 0.22;
            d[i] = (click + thud + ring + ring2 + noise) * env;
        }

        const revLen = Math.floor(sr * 1.4);
        const revBuf = ctx.createBuffer(2, revLen, sr);
        for (let ch = 0; ch < 2; ch++) {
            const rd = revBuf.getChannelData(ch);
            for (let i = 0; i < revLen; i++) {
                rd[i] = (Math.random() * 2 - 1) * Math.exp(-i / (sr * 0.17));
            }
        }

        const conv  = ctx.createConvolver(); conv.buffer = revBuf;
        const src   = ctx.createBufferSource(); src.buffer = snapBuf;
        const dry   = ctx.createGain(); dry.gain.value   = 1.0;
        const wet   = ctx.createGain(); wet.gain.value   = 0.5;
        const master= ctx.createGain(); master.gain.value= 0.8;

        src.connect(dry); src.connect(conv);
        conv.connect(wet);
        dry.connect(master); wet.connect(master);
        master.connect(ctx.destination);
        src.start();
    } catch(e) {}
}

