// ── Snap effect (sound + visuals) ─────────────────────────────────────────────
function cwSnapEffect() {
    playSnapLock();

    // Purple screen flash
    const flash = document.createElement('div');
    flash.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:9990;' +
        'background:rgba(124,58,237,0.13);animation:cw-screen-flash 0.32s ease-out forwards;';
    document.body.appendChild(flash);
    flash.addEventListener('animationend', () => flash.remove());

    // Shake the wrap
    const wrap = document.querySelector('.cw-chain-track');
    if (wrap) {
        wrap.style.animation = 'none';
        void wrap.offsetWidth;
        wrap.style.animation = 'cw-shake 0.32s ease-out';
        wrap.addEventListener('animationend', () => { wrap.style.animation = ''; }, { once: true });
    }

    // Burst ring + particles at the last node
    setTimeout(() => {
        const nodes = document.querySelectorAll('.cw-node');
        const last  = nodes[nodes.length - 1];
        if (!last) return;
        const r  = last.getBoundingClientRect();
        const cx = r.left + r.width  / 2;
        const cy = r.top  + r.height / 2;

        // Expanding ring
        const ring = document.createElement('div');
        ring.style.cssText = `position:fixed;left:${cx}px;top:${cy}px;width:56px;height:56px;
            border-radius:50%;border:3px solid rgba(167,139,250,0.9);pointer-events:none;z-index:9991;
            animation:cw-burst-ring 0.52s ease-out forwards;`;
        document.body.appendChild(ring);
        ring.addEventListener('animationend', () => ring.remove());

        // Second ring (delayed)
        const ring2 = document.createElement('div');
        ring2.style.cssText = `position:fixed;left:${cx}px;top:${cy}px;width:56px;height:56px;
            border-radius:50%;border:2px solid rgba(251,191,36,0.6);pointer-events:none;z-index:9991;
            animation:cw-burst-ring 0.6s 0.1s ease-out forwards;`;
        document.body.appendChild(ring2);
        ring2.addEventListener('animationend', () => ring2.remove());

        // Spark particles
        const COLS = ['#A78BFA','#C4B5FD','#DDD6FE','#FBBF24','#34D399','#818CF8'];
        for (let i = 0; i < 14; i++) {
            const angle = (i / 14) * 360 + (Math.random() - 0.5) * 26;
            const dist  = 40 + Math.random() * 42;
            const dx    = Math.cos(angle * Math.PI / 180) * dist;
            const dy    = Math.sin(angle * Math.PI / 180) * dist;
            const sz    = 3 + Math.random() * 3.5;
            const col   = COLS[Math.floor(Math.random() * COLS.length)];
            const dur   = 0.45 + Math.random() * 0.25;
            const p     = document.createElement('div');
            p.style.cssText = `position:fixed;left:${cx}px;top:${cy}px;
                width:${sz}px;height:${sz}px;border-radius:50%;
                background:${col};box-shadow:0 0 5px ${col};
                pointer-events:none;z-index:9992;
                --pdx:${dx}px;--pdy:${dy}px;
                animation:cw-particle ${dur}s ease-out forwards;`;
            document.body.appendChild(p);
            p.addEventListener('animationend', () => p.remove());
        }
    }, 30);
}

// ── State ──────────────────────────────────────────────────────────────────────
let cw = null;

// ── Puzzle generator ───────────────────────────────────────────────────────────
function generateCWPuzzle(level) {
    const numCount = Math.min(3 + Math.floor((level - 1) / 3), 7);
    const useMult  = level >= 3;
    const useDiv   = level >= 6;
    const maxVal   = Math.min(4 + level * 3, 40);

    let attempts = 0;
    while (attempts++ < 120) {
        const nums  = Array.from({ length: numCount }, () => Math.floor(Math.random() * maxVal) + 2);
        const order = [...nums].sort(() => Math.random() - 0.5);
        let current = order[0];
        const chain = [];
        let valid   = true;

        for (let i = 1; i < order.length; i++) {
            const n = order[i];
            const ops = ['+', '-'];
            if (useMult) ops.push('×');
            if (useDiv && n !== 0 && current % n === 0 && current / n > 0) ops.push('÷');

            const legal = ops.filter(op => {
                if (op === '+') return current + n <= 999;
                if (op === '-') return current - n > 0;
                if (op === '×') return current * n <= 999;
                if (op === '÷') return n !== 0 && current % n === 0 && current / n > 0;
                return false;
            });

            if (!legal.length) { valid = false; break; }
            const op  = legal[Math.floor(Math.random() * legal.length)];
            const res = op==='+' ? current+n : op==='-' ? current-n : op==='×' ? current*n : current/n;
            chain.push({ op, num: n, result: res });
            current = res;
        }

        if (!valid) continue;
        const tiles = [...nums].sort(() => Math.random() - 0.5);
        return { tiles, startNum: order[0], target: current, solution: chain, level };
    }

    return { tiles:[3,4,2], startNum:3, target:20, solution:[{op:'+',num:4,result:7},{op:'×',num:2,result:14}], level };
}

// ── Entry / Exit ───────────────────────────────────────────────────────────────
function showChainWeaver() {
    if (!user) { showToast('Please sign in first'); return; }
    stopGauntlet();
    hideAll();
    const sec = document.getElementById('section-chain');
    sec.classList.remove('hidden');
    playEnter(sec);
    document.getElementById('bottom-nav').style.display = 'none';

    const level  = user.chainLevel  || 1;
    const streak = user.chainStreak || 0;
    const puzzle = generateCWPuzzle(level);

    cw = { puzzle, remaining: [...puzzle.tiles], used: [], chain: [],
           current: null, phase: 'pick-start', selectedOp: null,
           sessionScore: 0, streak, level };
    cwRender();
}

function cwExit() {
    if (user && cw) { user.chainStreak = cw.streak; save(); }
    cw = null;
    document.getElementById('bottom-nav').style.display = '';
    showDashboard();
}

// ── Tile interaction ───────────────────────────────────────────────────────────
function cwPickTile(value, idx) {
    if (!cw) return;

    if (cw.phase === 'pick-start') {
        cw.current = value;
        cw.remaining.splice(idx, 1);
        cw.used.push({ value });
        cw.phase = 'pick-op';
        cwSnapEffect();
        cwRender();
        return;
    }

    if (cw.phase === 'pick-num' && cw.selectedOp) {
        const op = cw.selectedOp;
        const n  = value;
        let result;

        if      (op === '+') result = cw.current + n;
        else if (op === '-') result = cw.current - n;
        else if (op === '×') result = cw.current * n;
        else {
            if (n === 0 || cw.current % n !== 0) { showToast('Must divide evenly — pick another number'); return; }
            result = cw.current / n;
        }

        if (!Number.isInteger(result) || result <= 0) { showToast('Result must be a positive whole number'); return; }
        if (result > 999999) { showToast('Result too large'); return; }

        cw.chain.push({ op, num: n, result, prevVal: cw.current });
        cw.used.push({ value: n });
        cw.remaining.splice(idx, 1);
        cw.current    = result;
        cw.selectedOp = null;
        cw.phase      = cw.remaining.length > 0 ? 'pick-op' : 'done';

        cwSnapEffect();
        if (cw.phase === 'done') { setTimeout(cwCheck, 400); return; }
        cwRender();
    }
}

function cwPickRemainingTile(val) {
    if (!cw) return;
    const idx = cw.remaining.indexOf(val);
    if (idx === -1) return;
    cwPickTile(val, idx);
}

// ── Operator selection ─────────────────────────────────────────────────────────
function cwSelectOp(op) {
    if (!cw || (cw.phase !== 'pick-op' && cw.phase !== 'pick-num')) return;
    cw.selectedOp = (cw.selectedOp === op) ? null : op;
    cw.phase      = cw.selectedOp ? 'pick-num' : 'pick-op';
    cwRender();
}

// ── Undo ───────────────────────────────────────────────────────────────────────
function cwUndo() {
    if (!cw) return;
    if (cw.phase === 'pick-num' && cw.selectedOp) {
        cw.selectedOp = null; cw.phase = 'pick-op'; cwRender(); return;
    }
    if (cw.chain.length === 0 && cw.current !== null) {
        cw.remaining.unshift(cw.used.pop().value);
        cw.current = null; cw.phase = 'pick-start'; cwRender(); return;
    }
    if (cw.chain.length > 0) {
        const last = cw.chain.pop();
        cw.remaining.unshift(cw.used.pop().value);
        cw.current    = last.prevVal;
        cw.selectedOp = null;
        cw.phase      = 'pick-op';
        cwRender();
    }
}

// ── Win / Loss ─────────────────────────────────────────────────────────────────
function cwCheck() {
    const { target, level } = cw.puzzle;
    const won = cw.current === target;
    let earned = 0;

    if (won) {
        cw.streak++;
        const sBonus = Math.min(cw.streak - 1, 10);
        earned = Math.round((20 + level * 4) * (1 + sBonus * 0.2));
        cw.sessionScore += earned;
        if (user) {
            user.coins       = (user.coins || 0) + earned;
            user.chainLevel  = Math.min((user.chainLevel || 1) + 1, 50);
            user.chainStreak = cw.streak;
            user.weeklyScore = (user.weeklyScore || 0) + earned;
            save();
        }
        if (cw.streak > 1 && cw.streak % 3 === 0) cwFlashMult('STREAK x' + cw.streak);
        playCorrect();
    } else {
        cw.streak = 0;
        if (user) { user.chainStreak = 0; save(); }
        playFail();
    }
    cwShowResult(won, earned);
}

function cwFlashMult(text) {
    const el = document.createElement('div');
    el.className = 'cw-mult-flash'; el.textContent = text;
    document.body.appendChild(el);
    el.addEventListener('animationend', () => el.remove());
}

// ── Result screen ──────────────────────────────────────────────────────────────
function cwShowResult(won, earned) {
    const sec = document.getElementById('section-chain');
    sec.innerHTML = '';
    const solutionLine = cw.puzzle.solution.map(s => `${s.op}${s.num}`).join(' → ');
    const chainHTML    = cwBuildChainHTML(true);
    const div = document.createElement('div');
    div.className = 'cw-result';

    if (won) {
        div.innerHTML = `
            <div class="cw-result-icon">⚡</div>
            <h2 class="cw-result-title" style="color:#34D399">CHAIN SOLVED!</h2>
            <div style="font-family:var(--font-display);font-size:1.6rem;color:#FBBF24;letter-spacing:0.06em;text-shadow:0 0 30px rgba(251,191,36,0.6)">+${earned} 🪙</div>
            <p class="cw-result-sub">Streak: ${cw.streak} &nbsp;·&nbsp; Session: ${cw.sessionScore} 🪙</p>
            <div class="cw-result-chain">${chainHTML}</div>
            <div style="display:flex;gap:12px;margin-top:24px;width:100%">
                <button class="main-btn" onclick="cwNext()" style="flex:1">NEXT CHAIN →</button>
                <button class="main-btn btn-ghost" onclick="cwExit()" style="flex:1">Exit</button>
            </div>`;
    } else {
        div.innerHTML = `
            <div class="cw-result-icon">💀</div>
            <h2 class="cw-result-title" style="color:#EF4444">CHAIN BROKEN</h2>
            <p class="cw-result-sub">Reached <strong>${cw.current}</strong>, needed <strong>${cw.puzzle.target}</strong></p>
            <p class="cw-result-sub">Streak reset</p>
            <div class="cw-result-chain">${chainHTML}</div>
            <div class="cw-solution-box">
                <strong>One solution:</strong><br>
                ${cw.puzzle.startNum} → ${solutionLine} = ${cw.puzzle.target}
            </div>
            <div style="display:flex;gap:12px;margin-top:24px;width:100%">
                <button class="main-btn" onclick="cwNext()" style="flex:1">TRY AGAIN →</button>
                <button class="main-btn btn-ghost" onclick="cwExit()" style="flex:1">Exit</button>
            </div>`;
    }
    sec.appendChild(div);
}

function cwNext() { showChainWeaver(); }

// ── Chain HTML builder ─────────────────────────────────────────────────────────
function cwBuildChainHTML(forResult = false) {
    if (cw.current === null && !forResult) return '';
    const startDisplay = cw.chain.length === 0 ? cw.current : cw.puzzle.solution.length > 0
        ? (cw.used[0]?.value ?? cw.puzzle.startNum) : cw.puzzle.startNum;

    let html = `<span class="cw-node cw-node-start">${startDisplay ?? cw.puzzle.startNum}</span>`;
    cw.chain.forEach(step => {
        html += `
            <div class="cw-chain-connector">
                <span class="cw-chain-op-label">${step.op}${step.num}</span>
                ${cwChainLinkSVG()}
            </div>
            <span class="cw-node cw-node-mid">${step.result}</span>`;
    });
    return html;
}

// ── Renderer ───────────────────────────────────────────────────────────────────
function cwRender() {
    const sec = document.getElementById('section-chain');
    if (!sec || !cw) return;

    const { target, level } = cw.puzzle;
    const opsAvail   = level < 3 ? ['+', '-'] : level < 6 ? ['+', '-', '×'] : ['+', '-', '×', '÷'];
    const opsDisabled = cw.phase !== 'pick-op' && cw.phase !== 'pick-num';

    const phaseText = cw.phase === 'pick-start' ? 'TAP A NUMBER TO START YOUR CHAIN'
                    : cw.phase === 'pick-op'    ? 'SELECT AN OPERATOR'
                    : cw.phase === 'pick-num'   ? `PICK A NUMBER TO APPLY  ${cw.selectedOp}`
                    : '';
    const phaseCls  = cw.phase === 'pick-op' ? 'phase-pick-op'
                    : cw.phase === 'pick-num' ? 'phase-pick-num' : '';

    const opBtns = opsAvail.map(op => `
        <button class="cw-op-btn ${cw.selectedOp === op ? 'cw-op-active' : ''}"
                onclick="cwSelectOp('${op}')" ${opsDisabled ? 'disabled' : ''}>${op}</button>`
    ).join('');

    const undoBtn = (cw.chain.length > 0 || cw.current !== null || (cw.phase === 'pick-num' && cw.selectedOp))
        ? `<button class="cw-undo-btn" onclick="cwUndo()">↩ UNDO</button>` : '';

    // Tile state resolution (handles duplicates correctly)
    const tileBtns = cw.puzzle.tiles.map((val, i) => {
        let usedCount = 0;
        cw.used.forEach(u => { if (u.value === val) usedCount++; });
        let remCount = 0;
        cw.remaining.forEach(r => { if (r === val) remCount++; });

        let usedSoFar = 0, tileState = 'dim';
        for (let j = 0; j <= i; j++) {
            if (cw.puzzle.tiles[j] === val) {
                if (usedSoFar < usedCount) { if (j === i) tileState = 'used'; usedSoFar++; }
                else {
                    if (j === i) {
                        const canPick = cw.phase === 'pick-start' || cw.phase === 'pick-num';
                        tileState = (remCount > 0 && canPick) ? 'avail' : 'dim';
                    }
                }
            }
        }

        const cls     = tileState === 'used'  ? 'cw-num-tile cw-num-tile-used'
                      : tileState === 'avail' ? 'cw-num-tile cw-num-tile-available'
                      :                         'cw-num-tile cw-num-tile-dimmed';
        const handler = tileState === 'avail' ? `onclick="cwPickRemainingTile(${val})"` : '';
        return `<div class="${cls}" ${handler}>${val}</div>`;
    }).join('');

    const chainTrack    = cwBuildChainHTML();
    const currentDisplay = cw.current !== null
        ? `<div class="cw-current-block">
               <div class="cw-label">CURRENT</div>
               <div class="cw-current-val">${cw.current}</div>
           </div>` : '';

    sec.innerHTML = `
        <div class="cw-wrap">
            <div class="cw-topbar">
                <div class="cw-topbar-left">
                    <div class="cw-label">CHAIN WEAVER · LV ${level}</div>
                    <div class="cw-streak-badge">${cw.streak > 0 ? '🔥 ' + cw.streak : ''}</div>
                </div>
                <button class="cw-exit-btn" onclick="cwExit()">✕ Exit</button>
            </div>

            <div class="cw-target-block">
                <div>
                    <div class="cw-label">TARGET</div>
                    <div class="cw-target-num">${target}</div>
                </div>
                ${currentDisplay}
            </div>

            ${chainTrack ? `<div class="cw-chain-track">${chainTrack}</div>` : ''}

            <div class="cw-phase-bar ${phaseCls}">${phaseText}</div>

            <div class="cw-ops-row">${opBtns}${undoBtn}</div>

            <div>
                <div class="cw-label" style="margin-bottom:10px">YOUR NUMBERS — USE ALL</div>
                <div class="cw-num-tiles">${tileBtns}</div>
            </div>

            <div class="cw-scorebar">
                <span>${cw.streak > 0 ? '🔥 ' + cw.streak + ' streak' : ''}</span>
                <span>Session: <strong>${cw.sessionScore}</strong> 🪙</span>
            </div>
        </div>`;

    setTimeout(() => {
        const track = document.querySelector('.cw-chain-track');
        if (track) track.scrollLeft = track.scrollWidth;
    }, 60);
}
